// SearchService: orchestrates unified search across repos, checkpoints, commits, and PRs.
// All full-text and semantic search goes through a single Turbopuffer query per org namespace.
// Tier-based pipeline: tier 0 (full keyword match), tier 1 (partial + top ANN, Cohere reranked),
// tier 2 (remaining ANN, capped).

import type { PostHog } from "posthog-node"

import { getAccessibleReposByUser, searchReposByUser } from "./planetscale/repos"
import {
  getCheckpointsByIdsGlobal,
  getCommitsByShasGlobal,
  getPRsByGithubIdsGlobal,
} from "./planetscale/search-queries"
import { isFeatureEnabled } from "./posthog"
import { rerankTier1 } from "./search-reranker"
import type {
  SearchMatchType,
  SearchResult,
  SearchResponse,
  SearchParams,
  SearchTier,
  CheckpointResult,
  CommitResult,
  PRResult,
} from "./search-types"
import type { UnifiedSearchRow } from "./turbopuffer"
import { embedQueryVector, searchChunksOrg } from "./turbopuffer"

export type { SearchResult, SearchResponse, SearchParams }

// Max concurrent org namespace queries
const ORG_QUERY_CONCURRENCY = 5

// Tier pipeline constants
const MAX_TIER2 = 15 // cap on tier 2 results

// Check if the full query phrase appears in any of the Turbopuffer text fields.
// For single-word queries, this checks for the word. For multi-word, checks the
// exact phrase in order.
function isFullQueryMatch(query: string, hit: UnifiedSearchRow): boolean {
  const q = query.toLowerCase()
  for (const text of [hit.title_text, hit.meta_text, hit.chunk_text]) {
    if (text && text.toLowerCase().includes(q)) return true
  }
  return false
}

// Assign tier and matchType from Turbopuffer hit data
function assignHitTier(
  query: string,
  hit: UnifiedSearchRow,
): { tier: SearchTier; matchType: SearchMatchType } {
  let tier: SearchTier
  if (hit.bm25Score !== null && isFullQueryMatch(query, hit)) {
    tier = 0
  } else if (hit.bm25Score !== null) {
    tier = 1 // BM25 matched but only partial
  } else {
    tier = 2 // ANN-only, will be promoted to tier 1 or capped later
  }

  const matchType: SearchMatchType =
    hit.bm25Score !== null && hit.annScore !== null
      ? "both"
      : hit.bm25Score !== null
        ? "keyword"
        : "semantic"

  return { tier, matchType }
}

// Apply a small recency boost to BM25 scores (higher = better).
// Skipped for ANN-only results where lower cosine distance = better.
function applyRecencyBoost(score: number, createdAt: string, isAnnOnly: boolean): number {
  if (isAnnOnly || !createdAt) return score
  const ageDays = (Date.now() - new Date(createdAt).getTime()) / (1000 * 60 * 60 * 24)
  return score * (1.0 + 0.1 * Math.max(0, 1 - ageDays / 30))
}

