export class SearchService {
  constructor(
    private readonly db: any,
    private readonly turbopufferApiKey: string | undefined,
    private readonly openaiApiKey: string | undefined,
    private readonly semanticSearchEnabled: boolean,
    private readonly cache?: KVNamespace,
    private readonly posthog?: PostHog | null,
    private readonly cohereApiKey?: string,
    private readonly skipFeatureFlags?: boolean,
  ) {}

  async search(userId: string, params: SearchParams): Promise<SearchResponse> {
    const totalStart = Date.now()
    const { types = ["repos", "checkpoints", "commits", "prs"] } = params
    const allResults: SearchResult[] = []

    let embedding_ms: number | null = null
    let vector_ms: number | null = null
    let rerank_ms: number | null = null
    let reranked: boolean | undefined

    if (types.includes("repos")) {
      const repos = await this.searchRepos(userId, params)
      allResults.push(...repos)
    }

    // Unified search covers checkpoints, commits, and PRs via Turbopuffer
    const searchTypes = types.filter((t) => t !== "repos")
    if (searchTypes.length > 0 && this.semanticSearchEnabled) {
      const embedStart = Date.now()
      const queryVector = await embedQueryVector(this.openaiApiKey!, params.q)
      embedding_ms = Date.now() - embedStart

      const vectorStart = Date.now()
      const results = await this.searchUnified(userId, params, queryVector, searchTypes)
      vector_ms = Date.now() - vectorStart
      allResults.push(...results)
    }

    // Separate into tiers
    const tier0: SearchResult[] = []
    const tier1: SearchResult[] = []
    let tier2: SearchResult[] = []
    const repoResults: SearchResult[] = []

    for (const r of allResults) {
      if (r.type === "repo") {
        repoResults.push(r)
        continue
      }
      if (r.searchMeta.tier === 0) tier0.push(r)
      else if (r.searchMeta.tier === 1) tier1.push(r)
      else tier2.push(r)
    }

    // Tier 0: sort by bm25Score desc (no rerank)
    tier0.sort((a, b) => (b.searchMeta.bm25Score ?? 0) - (a.searchMeta.bm25Score ?? 0))

    // Cohere relevance threshold: 0.3 baseline, may tighten later once we
    // have more data on score distributions.
    const hasKeywordMatches = tier0.length > 0
    const minRelevance = hasKeywordMatches ? 0.3 : 0.2

    // Tier 1: Cohere rerank with relevance threshold (BM25/hybrid results only)
    if (this.cohereApiKey && tier1.length > 0) {
      const rerankStart = Date.now()
      const rerankOutput = await rerankTier1(
        this.cohereApiKey,
        params.q,
        tier1,
        minRelevance,
        this.cache,
      )
      rerank_ms = Date.now() - rerankStart
      reranked = rerankOutput.reranked
      tier1.splice(0, tier1.length, ...rerankOutput.results)
    }

    // Append top 10% of ANN-only results (tier 2) after Cohere-reranked tier 1.
    // This prevents semantic-only results from being ranked above keyword matches
    // by the reranker when they lack sufficient context.
    // Guard on cohereApiKey: without Cohere, tier 1 may be empty and we'd
    // discard remaining tier 2 results by making tier1 non-empty.
    let promoted: SearchResult[] = []
    if (this.cohereApiKey && tier2.length > 0) {
      tier2.sort((a, b) => a.searchMeta.score - b.searchMeta.score)
      const promotionCount = Math.max(1, Math.ceil(tier2.length * 0.1))
      promoted = tier2.splice(0, promotionCount)
      tier1.push(...promoted)
    }

    // Tier 2: only show when tier 0+1 are empty (nothing relevant found).
    if (tier0.length > 0 || tier1.length > 0) {
      tier2 = []
    } else {
      tier2.unshift(...promoted)
      tier2.sort(
        (a, b) =>
          (a.searchMeta.annScore ?? a.searchMeta.score) -
          (b.searchMeta.annScore ?? b.searchMeta.score),
      )
      tier2.splice(MAX_TIER2)
    }

    // Diagnostic log
    console.log(
      `[search] tier_distribution`,
      JSON.stringify({
        tier0: tier0.length,
        tier1: tier1.length,
        tier2: tier2.length,
        repos: repoResults.length,
        minRelevance,
      }),
    )

    // Combine: [repos] + [tier 0] + [tier 1] + [tier 2]
    const finalResults = [...repoResults, ...tier0, ...tier1, ...tier2]

    const total = finalResults.length
    const safePage = Math.max(1, params.page)
    const start = (safePage - 1) * params.limit
    // Compute per-type counts from the full result set (before pagination)
    const counts = { repos: 0, checkpoints: 0, commits: 0, prs: 0 }
    for (const r of finalResults) {
      if (r.type === "repo") counts.repos++
      else if (r.type === "checkpoint") counts.checkpoints++
      else if (r.type === "commit") counts.commits++
      else if (r.type === "pr") counts.prs++
    }

    const results = finalResults.slice(start, start + params.limit)
    const total_ms = Date.now() - totalStart

    return {
      results,
      total,
      page: safePage,
      timing: { total_ms, keyword_ms: null, embedding_ms, vector_ms, rerank_ms },
      ...(reranked !== undefined && { reranked }),
      counts,
    }
  }

