// Search-specific DB queries used by the search worker.
// These are separate from the namespace factory pattern used by the API routes.

import { Kysely, sql } from "kysely"

import type { DB } from "../../../db/types"
import { preferredBranchOrder } from "./branch-ranking"

// ─── User lookup ──────────────────────────────────────────────────────────────

export async function getUserByGithubId(
  db: Kysely<DB>,
  githubId: number,
): Promise<{ id: string; github_login: string | null } | null> {
  const row = await db
    .selectFrom("users")
    .select(["id", "github_login"])
    .where("github_id", "=", githubId)
    .executeTakeFirst()
  return row ?? null
}

// ─── Checkpoint hydration by IDs ──────────────────────────────────────────────

export async function getCheckpointsByIdsGlobal(
  db: Kysely<DB>,
  checkpointIds: string[],
  userId: string,
): Promise<any[]> {
  if (checkpointIds.length === 0) return []

  const branchOrder = preferredBranchOrder("bc.branch", "repos.default_branch")

  // Branch is read from repo_branch_commits (the source of truth) rather than
  // repo_checkpoint_commits.branch (last-writer-wins informational metadata).
  // Joining on (repo_id, commit_sha) fans out the result one row per branch the
  // commit lives on; the ORDER BY picks the repo's default branch first, then
  // the main/master fallbacks, then alphabetical. The dedup loop below keeps
  // one row per checkpoint, so each checkpoint surfaces under its preferred
  // branch in search results.
  const rows = await db
    .selectFrom("repo_checkpoints as cp")
    .innerJoin("repo_checkpoint_commits as cc", (join) =>
      join
        .onRef("cc.repo_id", "=", "cp.repo_id")
        .onRef("cc.checkpoint_id", "=", "cp.checkpoint_id"),
    )
    .innerJoin("repo_commits as rc", (join) =>
      join.onRef("rc.repo_id", "=", "cc.repo_id").onRef("rc.commit_sha", "=", "cc.commit_sha"),
    )
    .innerJoin("repos", "repos.id", "cp.repo_id")
    .innerJoin("repo_branch_commits as bc", (join) =>
      join.onRef("bc.repo_id", "=", "cc.repo_id").onRef("bc.commit_sha", "=", "cc.commit_sha"),
    )
    .innerJoin("user_repos", "user_repos.repo_id", "cp.repo_id")
    .where("user_repos.user_id", "=", userId)
    .where("cp.checkpoint_id", "in", checkpointIds)
    .select([
      "cp.checkpoint_id",
      "cp.prompt",
      "cp.files_touched",
      "cp.created_at",
      "rc.commit_message",
      "cc.commit_sha",
      "bc.branch",
      "rc.commit_author as author",
      "rc.commit_author_username as author_username",
      "repos.full_name as repo_full_name",
    ])
    .orderBy(branchOrder.defaultRank!)
    .orderBy(branchOrder.mainMasterRank)
    .orderBy(branchOrder.alphabetical, "asc")
    .execute()

  // Deduplicate: each checkpoint can appear on multiple branches; keep the
  // first row per checkpoint_id, which the ORDER BY ranked as preferred.
  const seen = new Set<string>()
  const deduped: typeof rows = []
  for (const row of rows) {
    if (!seen.has(row.checkpoint_id)) {
      seen.add(row.checkpoint_id)
      deduped.push(row)
    }
  }

  return deduped.map((row) => {
    const parts = (row.repo_full_name ?? "").split("/")
    return {
      ...row,
      org: parts[0] ?? "",
      repo: parts[1] ?? "",
    }
  })
}

