): Promise<any[]> {
  if (shas.length === 0) return []

  const rows = await db
    .selectFrom("repo_commits as rc")
    .innerJoin("repos", "repos.id", "rc.repo_id")
    .innerJoin("user_repos", "user_repos.repo_id", "repos.id")
    .innerJoin("repo_branch_commits as bc", (join) =>
      join.onRef("bc.repo_id", "=", "rc.repo_id").onRef("bc.commit_sha", "=", "rc.commit_sha"),
    )
    .where("user_repos.user_id", "=", userId)
    .where("rc.commit_sha", "in", shas)
    .select([
      "rc.id",
      "rc.commit_sha",
      "rc.commit_message",
      "rc.commit_author as author",
      "rc.commit_author_username as author_username",
      "rc.commit_date",
      "rc.additions",
      "rc.deletions",
      "rc.files_changed",
      "rc.html_url",
      "bc.branch",
      "repos.full_name as repo_full_name",
      "repos.github_id as repo_github_id",
    ])
    .orderBy("rc.commit_date", "desc")
    .execute()

  // Deduplicate: one row per commit_sha (keep first seen, ordered by date desc)
  const seen = new Set<string>()
  return rows.filter((row) => {
    if (seen.has(row.commit_sha)) return false
    seen.add(row.commit_sha)
    return true
  })
}

