// --- Config ---

const CHUNK_SIZE = 50 // process checkpoints in chunks of 50 (fetch transcripts + index per chunk)
const GITHUB_API = "https://api.github.com"
const TRANSCRIPT_CONCURRENCY = 15 // parallel GitHub API fetches per chunk
const MAX_TRANSCRIPT_CHARS = 200_000 // generous limit for user prompts + AI responses
const MAX_RETRIES = 3
const RETRY_BASE_DELAY_MS = 1000

// --- CLI Argument Parsing ---

interface CliOptions {
  repo: string | null
  repoId: string | null
  withTranscripts: boolean
  dryRun: boolean
  limit: number | null
}

function parseArgs(): CliOptions {
  const args = process.argv.slice(2)
  const options: CliOptions = {
    repo: null,
    repoId: null,
    withTranscripts: false,
    dryRun: false,
    limit: null,
  }

  for (let i = 0; i < args.length; i++) {
    switch (args[i]) {
      case "--repo":
        options.repo = args[++i]
        if (!options.repo) {
          console.error("Error: --repo requires a value (e.g., 'entireio/cli')")
          process.exit(1)
        }
        break
      case "--repo-id":
        options.repoId = args[++i]
        if (!options.repoId) {
          console.error("Error: --repo-id requires a UUID value")
          process.exit(1)
        }
        break
      case "--with-transcripts":
        options.withTranscripts = true
        break
      case "--dry-run":
        options.dryRun = true
        break
      case "--limit":
        options.limit = parseInt(args[++i], 10)
        if (isNaN(options.limit) || options.limit <= 0) {
          console.error("Error: --limit requires a positive integer")
          process.exit(1)
        }
        break
      default:
        console.error(`Unknown option: ${args[i]}`)
        console.error(
          "Usage: pnpm exec tsx scripts/backfill-search.ts [--repo <name>] [--repo-id <uuid>] [--with-transcripts] [--dry-run] [--limit <n>]",
        )
        process.exit(1)
    }
  }

  return options
}

// --- Database Setup ---

function createDb(): Kysely<DB> {
  const url = process.env.DATABASE_URL ?? "REDACTED"
  const parsed = new URL(url)
  const isLocalhost = parsed.hostname === "localhost" || parsed.hostname === "127.0.0.1"

  return new Kysely<DB>({
    dialect: new MysqlDialect({
      pool: createPool({
        host: parsed.hostname,
        port: Number(parsed.port) || 3306,
        user: decodeURIComponent(parsed.username),
        password: decodeURIComponent(parsed.password),
        database: parsed.pathname.replace("/", ""),
        ssl: isLocalhost ? undefined : { rejectUnauthorized: true },
      }),
    }),
  })
}

// --- Fetch with Retry ---

async function fetchWithRetry(url: string, options: RequestInit): Promise<Response> {
  for (let attempt = 0; attempt < MAX_RETRIES; attempt++) {
    try {
      const response = await fetch(url, options)
      // Retry on transient server errors and rate limits
      if (response.status >= 500 || response.status === 429) {
        if (attempt < MAX_RETRIES - 1) {
          const delay = RETRY_BASE_DELAY_MS * Math.pow(2, attempt)
          await sleep(delay)
          continue
        }
      }
      return response
    } catch (err) {
      if (attempt < MAX_RETRIES - 1) {
        const delay = RETRY_BASE_DELAY_MS * Math.pow(2, attempt)
        await sleep(delay)
        continue
      }
      throw err
    }
  }
  throw new Error("fetchWithRetry: exhausted retries")
}

