// Process a single batch of checkpoint IDs: fetch details, transcripts, build chunks, and index.
export async function processCheckpointBatch(
  db: Db,
  env: Env,
  repo: Repo,
  repoId: string,
  checkpointIds: string[],
  batchId: string,
): Promise<number> {
  const checkpoints = await db.checkpoints.getForSearchIndexing(repoId, checkpointIds)
  if (checkpoints.length === 0) return 0

  const checkpointRepoName = getCheckpointRepoName(repo)

  const transcriptsPromise = ensureTranscriptsStored(
    db,
    repoId,
    checkpointRepoName,
    repo.installation_id,
    checkpoints.map((cp) => ({
      checkpoint_id: cp.checkpoint_id,
      agent: cp.agent ?? LEGACY_FALLBACK_AGENT_NAME,
      session_count: cp.session_count ?? 1,
      sessions: (cp.sessions as SessionInfo[] | null) ?? null,
      storage_version: cp.storage_version ?? CHECKPOINT_V1_STORAGE_VERSION,
    })),
    env,
    batchId,
  )
  const analysesPromise = db.analyses.getByCheckpointIds(repoId, checkpointIds)
  const [transcripts, analysisRows] = await Promise.all([transcriptsPromise, analysesPromise])

  const analysesByCheckpointId = new Map<string, StoredCheckpointAnalysis>()
  for (const row of analysisRows) {
    if (row.status !== "complete") continue
    const { analysis, error } = parseStoredCheckpointAnalysis(row.analysis_json)
    if (error) {
      log("analysis_parse_error", {
        batchId,
        repoId,
        checkpointId: row.checkpoint_id,
        analysisId: row.id,
        error,
      })
    }
    if (analysis) {
      analysesByCheckpointId.set(row.checkpoint_id, analysis)
    }
  }

  // Build chunks for each checkpoint from its transcript (session 0),
  // falling back to a single metadata chunk when no transcript is available.
  const checkpointWithChunks = checkpoints.map((cp) => {
    const jsonl = transcripts.get(cp.checkpoint_id) ?? null
    let chunks: SearchChunk[] = []

    if (jsonl) {
      try {
        const { messages } = parseCheckpointTranscriptForIndexing(
          jsonl,
          cp.agent ?? LEGACY_FALLBACK_AGENT_NAME,
          cp.storage_version ?? CHECKPOINT_V1_STORAGE_VERSION,
        )
        const sessions = (cp.sessions as SessionInfo[] | null) ?? null
        const uuidBoundary = sessions?.[0]?.transcriptIdentifierAtStart ?? null
        const filtered = filterRelevantMessages(messages, uuidBoundary)
        chunks = chunkTranscript(filtered, cp.checkpoint_id)
      } catch {
        // fall through to metadata-only fallback below
      }
    }

    const analysis = analysesByCheckpointId.get(cp.checkpoint_id)

    if (chunks.length === 0) {
      // Fallback: single chunk from prompt + commit + files (no transcript)
      const analysisText = analysis ? buildCheckpointAnalysisRetrievalSummary(analysis) : null
      const text = buildSearchText({
        prompt: cp.prompt,
        commit_message: cp.commit_message,
        files_touched: cp.files_touched,
        analysis: analysisText || null,
      })
      if (text.trim()) {
        chunks = [
          {
            chunkId: makeChunkId(cp.checkpoint_id, 0),
            checkpointId: cp.checkpoint_id,
            chunkIndex: 0,
            text,
            turnStart: 0,
            turnEnd: 0,
            tokenEstimate: Math.ceil(text.length / 4),
            chunkVersion: CHUNK_VERSION,
          },
        ]
      }
    }
    if (analysis) {
      const analysisChunks = buildCheckpointAnalysisBlockChunks(
        analysis,
        cp.checkpoint_id,
        chunks.length,
      )
      chunks = [...chunks, ...analysisChunks]
    }

    return {
      checkpoint_id: cp.checkpoint_id,
      branch: cp.branch,
      agent: cp.agent,
      commit_author_username: cp.commit_author_username,
      created_at: cp.created_at,
      commit_sha: cp.commit_sha,
      commit_message: cp.commit_message,
      prompt: cp.prompt,
      files_touched: cp.files_touched,
      chunks,
    }
  })

  // Pass org info so chunks are dual-written to the org-level namespace.
  // Org name is derived from full_name (e.g., "acme/backend-api" → "acme").
  const orgName = repo.full_name.split("/")[0]
  const orgInfo: OrgInfo | undefined = orgName
    ? { orgName, repoGithubId: repo.github_id }
    : undefined

  return indexCheckpointChunks(
    env.TURBOPUFFER_API_KEY!,
    env.OPENAI_API_KEY!,
    repo.github_id,
    checkpointWithChunks,
    orgInfo,
  )
}

