// Read .entire/settings.json from a repo to discover checkpoint remote configuration.

import { fetchFileAtCommit } from "./github"

export const ENTIRE_SETTINGS_PATH = ".entire/settings.json"

export interface EntireSettings {
  strategy_options?: {
    checkpoint_remote?: {
      provider: string
      repo: string // e.g., "org/checkpoints-repo"
    }
    checkpoints_version?: number
    checkpoints_v2?: boolean
    push_v2_refs?: boolean
  }
}

function normalizeCheckpointsVersion(value: unknown): number | undefined {
  if (typeof value === "number" && Number.isFinite(value)) {
    return value
  }

  if (typeof value === "string" && /^-?\d+$/.test(value.trim())) {
    return Number(value)
  }

  return undefined
}

function normalizeEntireSettings(parsed: unknown): EntireSettings | null {
  if (!parsed || typeof parsed !== "object") {
    return null
  }

  const settings = parsed as EntireSettings & {
    strategy_options?: EntireSettings["strategy_options"] & {
      checkpoints_version?: unknown
    }
  }

  if (!settings.strategy_options || typeof settings.strategy_options !== "object") {
    return settings
  }

  return {
    ...settings,
    strategy_options: {
      ...settings.strategy_options,
      checkpoints_version: normalizeCheckpointsVersion(
        settings.strategy_options.checkpoints_version,
      ),
    },
  }
}

export function parseEntireSettings(content: string): EntireSettings | null {
  try {
    return normalizeEntireSettings(JSON.parse(content))
  } catch {
    return null
  }
}

/**
 * Read .entire/settings.json from a repo's default branch.
 * Returns null if file doesn't exist or is invalid JSON.
 */
export async function readEntireSettings(
  repoFullName: string,
  ref: string,
  token?: string,
): Promise<EntireSettings | null> {
  const content = await fetchFileAtCommit(repoFullName, ENTIRE_SETTINGS_PATH, ref, token)
  if (!content) return null
  return parseEntireSettings(content)
}

/**
 * Read .entire/settings.json and swallow any fetch/parse errors.
 * Callers get `null` on error and can log via the optional `onError` callback.
 */
export async function readEntireSettingsSafe(
  repoFullName: string,
  ref: string,
  token: string | undefined,
  onError?: (err: unknown) => void,
): Promise<EntireSettings | null> {
  try {
    return await readEntireSettings(repoFullName, ref, token)
  } catch (err) {
    onError?.(err)
    return null
  }
}

/**
 * Extract checkpoint_repo_full_name from settings, or null if not configured.
 * Only supports provider "github" — matches CLI validation.
 */
export function getCheckpointRepoFromSettings(settings: EntireSettings | null): string | null {
  const remote = settings?.strategy_options?.checkpoint_remote
  if (!remote || remote.provider !== "github" || !remote.repo) return null
  // Validate repo format (must contain a slash: owner/name)
  if (!remote.repo.includes("/")) return null
  return remote.repo
}

function getOwner(fullName: string): string {
  return fullName.split("/")[0]?.toLowerCase() ?? ""
}

export interface CheckpointRepoResolution {
  /** Repo that holds the checkpoints (the configured remote, or the repo itself). */
  repo: string
  /**
   * Configured remote that was rejected because its owner differs from the
   * repo owner. Mirrors CLI behavior: a fork must push checkpoints to its own
   * origin, not into another owner's repo. Non-null means the resolver fell
   * back to the repo itself instead of using the configured remote.
   */
  rejectedRemote: string | null
}

/**
 * Resolve the checkpoint repo from settings, falling back to the repo itself.
 * After first sync, checkpoint_repo_full_name is always populated (either a
 * separate repo or the repo's own full_name as a "self" pointer).
 * Null means "never checked" — call this to populate it on first sync.
 */
export function resolveCheckpointRepo(
  repoFullName: string,
  settings: EntireSettings | null,
): CheckpointRepoResolution {
  const configured = getCheckpointRepoFromSettings(settings)
  if (!configured) return { repo: repoFullName, rejectedRemote: null }
  if (getOwner(configured) !== getOwner(repoFullName)) {
    return { repo: repoFullName, rejectedRemote: configured }
  }
  return { repo: configured, rejectedRemote: null }
}

/**
 * Check if checkpoints v2 is enabled in settings.
 * Returns true when the repo is explicitly configured for v2-only
 * (`checkpoints_version` is 2) or when legacy v2 flags are enabled.
 */
export function isCheckpointsV2Enabled(settings: EntireSettings | null): boolean {
  const strategyOptions = settings?.strategy_options
  const checkpointsVersion = strategyOptions?.checkpoints_version

  if (checkpointsVersion === 2) {
    return true
  }

  return strategyOptions?.checkpoints_v2 === true || strategyOptions?.push_v2_refs === true
}

/**
 * Get the effective checkpoint repo name from a repo record.
 * Falls back to full_name when checkpoint_repo_full_name hasn't been populated yet.
 */
export function getCheckpointRepoName(repo: {
  full_name: string
  checkpoint_repo_full_name: string | null
}): string {
  return repo.checkpoint_repo_full_name ?? repo.full_name
}

