// Queries `checkpoints-v2-org-{orgName}` with an ACL filter so each user only
// sees chunks belonging to repos they have access to.
// `accessibleRepoGithubIds` must be pre-filtered to repos within this org.
export async function searchChunksOrg(
  turbopufferApiKey: string,
  openaiApiKey: string,
  orgName: string,
  query: string,
  accessibleRepoGithubIds: number[],
  filters?: { branch?: string; docTypes?: string[] },
  limit: number = 50,
  cache?: KVNamespace,
  queryVector?: number[],
): Promise<UnifiedSearchRow[]> {
  const namespace = `checkpoints-v2-org-${orgName}`
  const startMs = Date.now()

  // Skip namespaces known to be missing (negative cache)
  if (cache) {
    const missing = await cache.get(nsMissingKey(namespace))
    if (missing) {
      console.log(
        `[search] chunk_search_skipped`,
        JSON.stringify({ namespace, reason: "ns_missing_cache" }),
      )
      return []
    }
  }

  if (accessibleRepoGithubIds.length === 0) return []

  const vector = queryVector ?? (await embedQueryVector(openaiApiKey, query))

  const headers = {
    Authorization: `Bearer ${turbopufferApiKey}`,
    "Content-Type": "application/json",
  }

  // Build ACL + optional filters
  const aclFilters: unknown[] = [["repo_github_id", "In", accessibleRepoGithubIds]]
  if (filters?.branch) {
    aclFilters.push(["branch", "Eq", filters.branch])
  }
  if (filters?.docTypes && filters.docTypes.length > 0) {
    aclFilters.push(["doc_type", "In", filters.docTypes])
  }

  const queryUrl = `https://api.turbopuffer.com/v2/namespaces/${encodeURIComponent(namespace)}/query`
  const filterExpr = aclFilters.length > 1 ? ["And", aclFilters] : aclFilters[0]
  const includeAttrs = [
    "doc_id",
    "doc_type",
    "checkpoint_id",
    "chunk_text",
    "title_text",
    "meta_text",
    "repo_github_id",
  ]

  type RawRow = {
    id: number
    $dist: number
    doc_id?: string
    doc_type?: string
    checkpoint_id?: string
    chunk_text?: string
    title_text?: string
    meta_text?: string
    repo_github_id?: number
  }

  // Turbopuffer doesn't allow ANN inside Sum, so we fire weighted BM25 and ANN
  // as parallel requests and merge with RRF.
  const sharedQuery = { top_k: limit, include_attributes: includeAttrs, filters: filterExpr }
  const bm25Body = {
    ...sharedQuery,
    rank_by: [
      "Sum",
      [
        ["Product", 3, ["title_text", "BM25", query]],
        ["Product", 2, ["meta_text", "BM25", query]],
        ["chunk_text", "BM25", query],
      ],
    ],
  }
  const annBody = { ...sharedQuery, rank_by: ["vector", "ANN", vector] }

  async function fireQuery(body: unknown): Promise<RawRow[]> {
    const resp = await fetchWithRetry(queryUrl, {
      method: "POST",
      headers,
      body: JSON.stringify(body),
    })
    if (!resp.ok) {
      const text = await resp.text().catch(() => "")
      if (resp.status === 404 && cache) {
        await cache.put(nsMissingKey(namespace), "1", { expirationTtl: NS_MISSING_TTL })
      }
      console.warn(`[search] org query failed (${resp.status}): ${text.slice(0, 200)}`)
      return []
    }
    const data = (await resp.json()) as { rows: RawRow[] }
    return data.rows ?? []
  }

  try {
    const [bm25Rows, annRows] = await Promise.all([fireQuery(bm25Body), fireQuery(annBody)])

    // Build a lookup for row data keyed by doc_id
    const rowDataById = new Map<string, RawRow>()
    for (const r of [...bm25Rows, ...annRows]) {
      const key = r.doc_id ?? r.checkpoint_id ?? String(r.id)
      if (!rowDataById.has(key)) rowDataById.set(key, r)
    }

    // Union + dedup: merge BM25 and ANN results by doc key, preserving raw scores
    const merged = new Map<
      string,
      {
        bm25Score: number | null
        annScore: number | null
        bm25Rank: number | null
        annRank: number | null
      }
    >()

    for (let rank = 0; rank < bm25Rows.length; rank++) {
      const r = bm25Rows[rank]
      const key = r.doc_id ?? r.checkpoint_id ?? String(r.id)
      const entry = merged.get(key) ?? {
        bm25Score: null,
        annScore: null,
        bm25Rank: null,
        annRank: null,
      }
      entry.bm25Score = r.$dist
      entry.bm25Rank = rank + 1
      merged.set(key, entry)
    }
    for (let rank = 0; rank < annRows.length; rank++) {
      const r = annRows[rank]
      const key = r.doc_id ?? r.checkpoint_id ?? String(r.id)
      const entry = merged.get(key) ?? {
        bm25Score: null,
        annScore: null,
        bm25Rank: null,
        annRank: null,
      }
      entry.annScore = r.$dist
      entry.annRank = rank + 1
      merged.set(key, entry)
    }

    // Checkpoint chunk collapse: preserve best bm25Score + best annScore + text from BM25 chunk
    const collapsed = new Map<
      string,
      {
        key: string
        bm25Score: number | null
        annScore: number | null
        bm25Rank: number | null
        annRank: number | null
      }
    >()

    for (const [key, s] of merged) {
      const r = rowDataById.get(key)
