const KV_LAST_FETCH_KEY = "posthog:flag-definitions:last-fetch"
// No expirationTtl — KV entries persist until overwritten by the next fetch.
// This avoids cold-start latency when an isolate spins up after a traffic gap:
// stale definitions are served instantly while a background refresh happens.
const FETCH_INTERVAL_SECONDS = 30 // Only fetch from PostHog API every 30s

// ─── KV-backed flag definition cache ─────────────────────────────────────────

export class KVFlagCacheProvider implements FlagDefinitionCacheProvider {
  kv: KVNamespace

  // Stale-while-revalidate: the SDK always reads from cache (fast path).
  // Background revalidation flips this to `true` temporarily so the SDK
  // actually fetches from PostHog when we call `reloadFeatureFlags()`.
  private _allowFetch = false

  constructor(kv: KVNamespace) {
    this.kv = kv
  }

  async getFlagDefinitions(): Promise<FlagDefinitionCacheData | undefined> {
    try {
      const raw = await this.kv.get(KV_KEY)
      if (!raw) return undefined
      return JSON.parse(raw)
    } catch {
      return undefined
    }
  }

  async shouldFetchFlagDefinitions(): Promise<boolean> {
    // During normal flag evaluation, only allow fetch if KV is completely empty.
    // This ensures the SDK's fallback fetch also writes to KV, seeding the cache.
    if (!this._allowFetch) {
      try {
        return (await this.kv.get(KV_KEY)) === null
      } catch {
        return true
      }
    }
    // Background revalidation — check actual staleness.
    try {
      const lastFetch = await this.kv.get(KV_LAST_FETCH_KEY)
      if (!lastFetch) return true
      const elapsed = (Date.now() - Number(lastFetch)) / 1000
      return elapsed >= FETCH_INTERVAL_SECONDS
    } catch {
      return true
    }
  }

  /** Check if the cached definitions are stale without triggering a fetch. */
  async needsRefresh(): Promise<boolean> {
    try {
      const lastFetch = await this.kv.get(KV_LAST_FETCH_KEY)
      if (!lastFetch) return true
      const elapsed = (Date.now() - Number(lastFetch)) / 1000
      return elapsed >= FETCH_INTERVAL_SECONDS
    } catch {
      return true
    }
  }

  enableFetch(): void {
    this._allowFetch = true
  }
  disableFetch(): void {
    this._allowFetch = false
